// Reference-added actions that no detector models are withheld from the catalog (engine/
// catalog-unmodeled.js, generated by scripts/gen-unmodeled-escalation.mjs), so an Allow of
// one stays an UNKNOWN_ACTION (exit 3) instead of reading CLEAN. A Deny of one is accepted.

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { defaultCatalog, ACCESS_LEVELS } from '../../../content/tools/iam-blast-radius/engine/catalog.js';
import { UNMODELED_ESCALATION } from '../../../content/tools/iam-blast-radius/engine/catalog-unmodeled.js';
import { AWS_REF_ACTIONS } from '../../../content/tools/iam-blast-radius/engine/catalog-aws-ref.js';
import { scan, EXIT } from '../../../cli/scan.mjs';

const ACCT = '123456789012';
const ec2 = `arn:aws:ec2:us-east-2:${ACCT}:res/name`;
const role = `arn:aws:iam::${ACCT}:role/admin`;

function run(statements, family = 'identity') {
  return scan({
    text: JSON.stringify({ Version: '2012-10-17', Statement: statements }),
    family, threshold: 'high', subjectAccount: ACCT, partition: 'aws',
  });
}
const allow = (Action, Resource = ec2) => ({ Effect: 'Allow', Action, Resource });
const ids = (r) => (r.findings || []).map((f) => f.id);
const codes = (r) => (r.analysisStates || []).map((s) => s.code);

test('every withheld action is a reference WRITE/PERMISSIONS action the catalog reports unknown', () => {
  assert.ok(UNMODELED_ESCALATION.length > 0);
  for (const key of UNMODELED_ESCALATION) {
    const [svc, action] = key.split(':');
    const refName = Object.keys(AWS_REF_ACTIONS[svc] || {}).find((n) => n.toLowerCase() === action);
    assert.ok(refName, `${key} is in the reference snapshot`);
    assert.ok(['WRITE', 'PERMISSIONS'].includes(AWS_REF_ACTIONS[svc][refName]), `${key} level`);
    const r = defaultCatalog.lookup(`${svc}:${refName}`);
    assert.equal(r.known, false, `${key} is withheld`);
    assert.equal(r.withheld, true, key);
  }
});

test('the ec2 escalation primitives the refresh made "known" fail closed in an Allow', () => {
  for (const action of [
    'ec2:ModifySnapshotAttribute', 'ec2:ModifyImageAttribute',
    'ec2:CreateNetworkInterfacePermission', 'ec2:ModifyInstanceAttribute',
    'ec2:ModifyVpcEndpointServicePermissions', 'ec2:DisableSnapshotBlockPublicAccess',
  ]) {
    const r = run([allow(action)]);
    assert.equal(r.exitCode, EXIT.FAIL_CLOSED, action);
    assert.ok(codes(r).includes('UNKNOWN_ACTION'), action);
  }
});

test('a Permissions-management action on a service outside the curated slice is withheld too', () => {
  const r = run([allow('sso:AttachManagedPolicyToPermissionSet', `arn:aws:sso:::permissionSet/ssoins-1/ps-1`)]);
  assert.equal(r.exitCode, EXIT.FAIL_CLOSED);
  assert.equal(defaultCatalog.lookup('sso:AttachManagedPolicyToPermissionSet').withheld, true);
});

test('instance-profile swap + iam:PassRole is a named PASSROLE-EC2 finding', () => {
  const r = run([
    allow(['ec2:AssociateIamInstanceProfile', 'ec2:ReplaceIamInstanceProfileAssociation']),
    allow('iam:PassRole', role),
  ]);
  assert.equal(r.exitCode, EXIT.FINDINGS);
  assert.ok(ids(r).includes('PASSROLE-EC2'), ids(r).join(','));
  // Without a PassRole grant in the policy the action alone is as clean as ec2:RunInstances.
  assert.equal(run([allow('ec2:AssociateIamInstanceProfile')]).exitCode, EXIT.CLEAN);
  assert.equal(run([allow('ec2:RunInstances')]).exitCode, EXIT.CLEAN);
});

test('a Deny of a withheld action, or of ec2:*, does not fail closed', () => {
  assert.equal(run([{ Effect: 'Deny', Action: 'ec2:ModifySnapshotAttribute', Resource: '*' }]).exitCode, EXIT.CLEAN);
  assert.equal(run([{ Effect: 'Deny', Action: 'ec2:Modify*', Resource: '*' }]).exitCode, EXIT.CLEAN);
  assert.equal(run([{ Effect: 'Deny', Action: 'ec2:*', Resource: '*' }]).exitCode, EXIT.CLEAN);
});

test('wildcards: one that expands to a withheld action is unsupported in an Allow; ec2:* stays WILDCARD-ACTION', () => {
  assert.equal(run([allow('ec2:Modify*')]).exitCode, EXIT.FAIL_CLOSED);
  assert.equal(defaultCatalog.classifyWildcard('ec2:Modify*').supported, false);
  const star = run([allow('ec2:*')]);
  assert.equal(star.exitCode, EXIT.FINDINGS);
  assert.ok(ids(star).includes('WILDCARD-ACTION'));
  assert.equal(defaultCatalog.classifyWildcard('ec2:*').supported, true);
  // Read-only enumeration is unaffected.
  assert.equal(run([allow('ec2:Describe*', '*')]).exitCode, EXIT.CLEAN);
});

test('LIST/READ reference actions stay known', () => {
  const r = defaultCatalog.lookup('ec2:DescribeInstanceAttribute');
  assert.equal(r.known, true);
  assert.equal(r.accessLevel, ACCESS_LEVELS.LIST);
});
